import { Link } from 'react-router-dom';
import copy from '../../data/siteCopy.json';
import './home-experience.css';

export default function HomeExperience({setHovered}) {
  return <section className="home-hero" aria-labelledby="rain-page-title">
    <div className="rain-hero-copy"><h1 id="rain-page-title" tabIndex={-1}>{copy.landingPage.fullName}</h1><p className="rain-subtitle">{copy.landingPage.subtitle}</p><p className="rain-description">{copy.landingPage.descriptionLines[0]}</p></div>
    <nav className="rain-destinations" aria-label="Explore Ray’s work">{copy.mainSections.items.map((item,i)=><Link key={item.id} to={`/${item.id}`} onPointerEnter={()=>setHovered(i)} onPointerLeave={()=>setHovered(-1)} onFocus={()=>setHovered(i)} onBlur={()=>setHovered(-1)}><span className="rain-destination-mark" aria-hidden="true"/><span>{item.title}</span><small>{item.description}</small></Link>)}</nav>
  </section>;
}
